namespace sarif.export.mm;





using generic.stl;
using ghidra.program.model.address;
using ghidra.program.model.mem;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.export;
using sarif.export;
using sarif.managers;
using sarif.managers;

public class SarifMemoryMapWriter : AbstractExtWriter {

	private List<Pair<AddressRange, MemoryBlock>> memory;
	private MemoryMapBytesFile bytesFile;
	private bool write;

	public SarifMemoryMapWriter(List<Pair<AddressRange, MemoryBlock>> request, Writer baseWriter,
			MemoryMapBytesFile bytes, bool isWriteContents)
    : base(baseWriter)
    {
		this.memory = request;
		this.bytesFile = bytes;
		this.write = isWriteContents;
	}

	/* @Override */
	protected void genRoot(TaskMonitor monitor)
    {
		genMaps(monitor);
		root.add("memory", objects);
	}

	private void genMaps(TaskMonitor monitor)
    {
		monitor.initialize(memory.size());
		foreach (Pair<AddressRange, MemoryBlock> m in memory) {
			monitor.checkCancelled();
			AddressRange range = m.first;
			ExtMemoryMap isf = new ExtMemoryMap(m.first, m.second, bytesFile, write);
			SarifObject sarif = new SarifObject(MemoryMapSarifMgr.SUBKEY, MemoryMapSarifMgr.KEY, getTree(isf),
					range.getMinAddress(), range.getMaxAddress());
			objects.add(getTree(sarif));
			monitor.increment();
		}
	}

}
